INSERT INTO documents (title, doc_type, author_organization, publication_year, publication_date, file_path, text_content) VALUES
('Анализ распространения COVID-19 в 2020 году', 'REPORT', 'НИИ Инфектологии', 2020, '2020-12-15', '/data/docs/2020/covid19_spread_analysis.pdf', 'В отчете представлен подробный анализ распространения вируса SARS-CoV-2. Рассмотрены основные пути передачи и эффективность карантинных мер в первые месяцы пандемии.'),
('Отчет по вспышке кори в регионе А', 'REPORT', 'Центр мониторинга инфекций', 2021, '2021-08-20', '/data/docs/2021/measles_outbreak_a.pdf', 'Детальный отчет о внезапной вспышке кори среди непривитого населения в регионе А. Описаны меры по локализации и проведению экстренной вакцинации.'),
('Приказ о мерах профилактики гриппа', 'ORDER', 'Министерство здравоохранения РФ', 2022, '2022-09-01', '/data/docs/2022/flu_prevention_order.pdf', 'Приказ содержит обязательные указания по подготовке медицинских учреждений к осенне-зимнему эпидемическому сезону гриппа и ОРВИ, включая обеспечение вакцинами.'),
('Эффективность новой вакцины против туберкулеза', 'EXTRACT', 'Учёный совет НИИ', 2023, '2023-04-10', '/data/docs/2023/tb_vaccine_efficacy.pdf', 'Выписка из протокола заседания ученого совета. Обсуждались предварительные результаты клинических испытаний новой рекомбинантной вакцины против туберкулеза, показавшей высокую эффективность.'),
('Результаты экзамена по клинической вирусологии', 'EXAM_RESULT', 'Факультет Вирусологии', 2023, '2023-06-25', '/data/docs/2023/clinical_virology_exams.pdf', 'Ведомость результатов весенней сессии. Студенты продемонстрировали глубокие знания в области клинической вирусологии и методов статистического анализа данных.'),
('Протокол испытаний антивирусного препарата Х', 'PROTOCOL', 'Лаборатория вирусологии', 2023, '2023-11-05', '/data/docs/2023/antiviral_x_trial.pdf', 'Протокол содержит данные второй фазы клинических испытаний нового антивирусного препарата Х. Отмечено снижение вирусной нагрузки у 85% пациентов.'),
('Мониторинг заболеваемости ВИЧ-инфекцией', 'REPORT', 'Центр профилактики СПИДа', 2024, '2024-02-15', '/data/docs/2024/hiv_monitoring.pdf', 'Годовой отчет по статистике новых случаев ВИЧ-инфекции. Наблюдается стабилизация уровня заболеваемости в ключевых группах риска благодаря профилактическим программам.'),
('Методические рекомендации по диагностике гепатита С', 'ORDER', 'Министерство здравоохранения РФ', 2024, '2024-03-20', '/data/docs/2024/hepc_diagnostic_guidelines.pdf', 'Обновленные рекомендации включают внедрение быстрых тестов и современных алгоритмов ПЦР-диагностики для раннего выявления вирусного гепатита С.'),
('Анализ резистентности к антибиотикам в стационарах', 'REPORT', 'НИИ Антимикробной терапии', 2024, '2024-05-10', '/data/docs/2024/antibiotic_resistance_study.pdf', 'В отчете представлены пугающие данные о росте устойчивости внутрибольничных штаммов бактерий к антибиотикам широкого спектра действия.'),
('Выписка о результатах проверки качества воды', 'EXTRACT', 'Санитарно-эпидемиологическая служба', 2024, '2024-07-01', '/data/docs/2024/water_quality_check.pdf', 'Документ подтверждает соответствие проб питьевой воды санитарным нормам после проведения плановой проверки очистных сооружений города.');
